import java.util.*; public class BibliotecaDesafio { private final String nome; private final List<String> livros=new ArrayList<>(); public BibliotecaDesafio(String n){if(n==null||n.isBlank())throw new IllegalArgumentException("nome");nome=n.trim();} public String getNome(){return nome;} public void adicionarLivro(String l){if(l!=null&&!l.isBlank())livros.add(l.trim());} public List<String> getLivros(){return new ArrayList<>(livros);} public static void main(String[] a){BibliotecaDesafio b=new BibliotecaDesafio("UNICAP");b.adicionarLivro("Java");System.out.println(b.getLivros());}}
